<?php
require_once 'config.php'; require_login('client'); $u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){ check_csrf(); if(isset($_POST['change_password'])){ $p=$_POST['password']??''; if(strlen($p)<8) flash('error','Password must be at least 8 characters.'); else { $st=db()->prepare('UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?'); $st->execute([password_hash($p,PASSWORD_DEFAULT),$u['id']]); $_SESSION['user']['must_change_password']=0; flash('success','Password changed successfully.'); } redirect('dashboard.php'); } }
$q=db()->prepare('SELECT * FROM quotes WHERE client_id=? ORDER BY created_at DESC');$q->execute([$u['id']]);$quotes=$q->fetchAll();
$p=db()->prepare('SELECT p.*, (SELECT update_text FROM project_updates pu WHERE pu.project_id=p.id ORDER BY pu.created_at DESC LIMIT 1) latest_update FROM projects p WHERE p.client_id=? ORDER BY p.updated_at DESC');$p->execute([$u['id']]);$projects=$p->fetchAll();
$updates=[]; foreach($projects as $pr){$st=db()->prepare('SELECT * FROM project_updates WHERE project_id=? ORDER BY created_at DESC');$st->execute([$pr['id']]);$updates[$pr['id']]=$st->fetchAll();}
$f=get_flash();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Dashboard</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f8fa;color:#232830;font-family:Arial,sans-serif}.top{background:#24384f;color:white;padding:18px 5%;display:flex;justify-content:space-between;align-items:center}.top a{color:white;text-decoration:none}.wrap{max-width:1100px;margin:30px auto;padding:0 20px}.notice{padding:13px;border-radius:8px;margin-bottom:18px;background:#e9f7ef;color:#166534}.error{background:#fff0ed;color:#9b3927}.card{background:white;border:1px solid #ddd;border-radius:12px;padding:20px;margin-bottom:20px}.bar{height:12px;background:#e3e7eb;border-radius:20px;overflow:hidden}.bar span{display:block;height:100%;background:#5b8db8}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}.muted{color:#68717d}input{padding:11px;width:100%;border:1px solid #ccd2d9;border-radius:7px}button{padding:11px 15px;border:0;border-radius:7px;background:#24384f;color:white;font-weight:700}ul{padding-left:20px}</style></head><body><header class="top"><strong>Andiswa Business Consultation — Client Portal</strong><a href="logout.php">Log out</a></header><main class="wrap"><h1>Welcome, <?=e($u['name'])?></h1><?php if($f):?><div class="notice <?=$f['type']==='error'?'error':''?>"><?=e($f['message'])?></div><?php endif;?><?php if($u['must_change_password']):?><div class="card"><h2>Change your temporary password</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="password" name="password" minlength="8" placeholder="New password" required><br><br><button name="change_password">Save password</button></form></div><?php endif;?><div class="grid"><section class="card"><h2>Your quote requests</h2><?php if(!$quotes):?><p class="muted">No quote has been linked to this account yet.</p><?php else: foreach($quotes as $x):?><div style="padding:12px 0;border-bottom:1px solid #eee"><strong><?=e($x['service'])?></strong><p><?=nl2br(e($x['message']))?></p><span class="muted">Status: <strong><?=e($x['status'])?></strong></span></div><?php endforeach; endif;?></section><section class="card"><h2>Your projects</h2><?php if(!$projects):?><p class="muted">A project will appear here once your quote has been accepted and the project has been created.</p><?php else: foreach($projects as $pr):?><div style="padding:12px 0;border-bottom:1px solid #eee"><h3><?=e($pr['title'])?></h3><p><?=e($pr['description'])?></p><p><strong><?=e($pr['status'])?></strong> — <?=e($pr['progress'])?>%</p><div class="bar"><span style="width:<?=min(100,(int)$pr['progress'])?>%"></span></div><?php if(!empty($pr['due_date'])):?><p class="muted">Due: <?=e($pr['due_date'])?></p><?php endif;?><h4>Updates</h4><?php if(empty($updates[$pr['id']])):?><p class="muted">No updates yet.</p><?php else:?><ul><?php foreach($updates[$pr['id']] as $up):?><li><?=e($up['update_text'])?> <small class="muted">(<?=e($up['created_at'])?>)</small></li><?php endforeach;?></ul><?php endif;?></div><?php endforeach; endif;?></section></div></main></body></html>
